DROP TABLE IF EXISTS "ai_usage";
DROP SEQUENCE IF EXISTS ai_usage_id_seq;
CREATE SEQUENCE ai_usage_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."ai_usage" (
    "id" integer DEFAULT nextval('ai_usage_id_seq') NOT NULL,
    "user_id" integer NOT NULL,
    "request_type" character varying(32) NOT NULL,
    "language" character varying(8) NOT NULL,
    "provider" character varying(32) NOT NULL,
    "model" character varying(128) NOT NULL,
    "retrieval_count" integer DEFAULT '0' NOT NULL,
    "gemini_called" boolean DEFAULT false NOT NULL,
    "input_tokens" integer DEFAULT '0' NOT NULL,
    "output_tokens" integer DEFAULT '0' NOT NULL,
    "total_tokens" integer DEFAULT '0' NOT NULL,
    "input_price_per_1m" numeric(18,10) DEFAULT '0' NOT NULL,
    "output_price_per_1m" numeric(18,10) DEFAULT '0' NOT NULL,
    "input_cost_usd" numeric(18,10) DEFAULT '0' NOT NULL,
    "output_cost_usd" numeric(18,10) DEFAULT '0' NOT NULL,
    "total_cost_usd" numeric(18,10) DEFAULT '0' NOT NULL,
    "duration_ms" integer DEFAULT '0' NOT NULL,
    "success" boolean DEFAULT true NOT NULL,
    "error_type" character varying(128),
    "created_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "ai_usage_pkey" PRIMARY KEY ("id")
) WITH (oids = false);

CREATE INDEX "ix_ai_usage_created_at" ON "public"."ai_usage" USING btree ("created_at");

CREATE INDEX "ix_ai_usage_request_type" ON "public"."ai_usage" USING btree ("request_type");

CREATE INDEX "ix_ai_usage_type_created" ON "public"."ai_usage" USING btree ("request_type", "created_at");

CREATE INDEX "ix_ai_usage_user_id" ON "public"."ai_usage" USING btree ("user_id");

