(64,	562520101,	'PAGE_TRANSLATION_UPDATED',	'BotPage',	'1',	'{"text": "Добро пожаловать!\n\nВыберите необходимый раздел:", "title": "Главное меню"}',	'{"text": "👋 Добро пожаловать в KUAM Bot!\nЗдесь вы можете узнать информацию об университете, образовательных программах, контактах, часто задаваемых вопросах и материалах.\nТакже вы можете воспользоваться ИИ-ассистентом для поиска информации.\nВыберите нужный раздел ниже 👇", "title": "Главное меню", "language": "ru"}',	'2026-10-02 05:13:16.294276+00'),
(65,	562520101,	'PAGE_TRANSLATION_UPDATED',	'BotPage',	'1',	'{"text": "Қош келдіңіз!\n\nҚажетті бөлімді таңдаңыз:", "title": "Басты мәзір"}',	'{"text": "👋 KUAM Bot-қа қош келдіңіз!\nМұнда университет, білім беру бағдарламалары, байланыс ақпараты, жиі қойылатын сұрақтар және материалдар туралы ақпарат ала аласыз.\nСондай-ақ ақпарат іздеу үшін ИИ-ассистентті пайдалана аласыз.\nҚажетті бөлімді төменнен таңдаңыз 👇", "title": "Басты мәзір", "language": "kk"}',	'2026-10-02 05:13:35.798687+00'),
