    "updated_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "bot_pages_key_key" UNIQUE ("key"),
    CONSTRAINT "bot_pages_pkey" PRIMARY KEY ("id")
) WITH (oids = false);

CREATE INDEX "ix_bot_pages_is_active" ON "public"."bot_pages" USING btree ("is_active");

CREATE INDEX "ix_bot_pages_key" ON "public"."bot_pages" USING btree ("key");

