DROP TABLE IF EXISTS "telegram_content_media";
DROP SEQUENCE IF EXISTS channel_post_media_id_seq;
CREATE SEQUENCE channel_post_media_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."telegram_content_media" (
    "id" integer DEFAULT nextval('channel_post_media_id_seq') NOT NULL,
    "content_post_id" integer NOT NULL,
    "source_message_id" integer NOT NULL,
    "type" channel_post_media_type NOT NULL,
    "telegram_file_id" character varying(512) NOT NULL,
    "file_unique_id" character varying(512),
    "file_name" character varying(255),
    "file_size" bigint,
    "position" integer DEFAULT '0' NOT NULL,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT "channel_post_media_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "uq_telegram_content_media_message" UNIQUE ("content_post_id", "source_message_id")
) WITH (oids = false);

CREATE INDEX "ix_telegram_content_media_content_post_id" ON "public"."telegram_content_media" USING btree ("content_post_id");


DROP TABLE IF EXISTS "telegram_content_posts";
DROP SEQUENCE IF EXISTS channel_posts_id_seq;
CREATE SEQUENCE channel_posts_id_seq INCREMENT 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1;

CREATE TABLE "public"."telegram_content_posts" (
    "id" integer DEFAULT nextval('channel_posts_id_seq') NOT NULL,
    "chat_id" bigint NOT NULL,
    "message_id" integer NOT NULL,
    "media_group_id" character varying(128),
    "status" telegram_content_status DEFAULT NEW NOT NULL,
    "text" text,
    "caption" text,
    "telegram_created_at" timestamptz,
    "processed_at" timestamptz,
    "processed_by" bigint,
    "created_page_id" integer,
    "created_faq_id" integer,
    "created_at" timestamptz DEFAULT now() NOT NULL,
    "updated_at" timestamptz DEFAULT now() NOT NULL,
    "chat_type" character varying(16) NOT NULL,
    "message_thread_id" integer,
    CONSTRAINT "channel_posts_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "uq_telegram_content_post_message" UNIQUE ("chat_id", "message_id")
) WITH (oids = false);

CREATE INDEX "ix_telegram_content_posts_group" ON "public"."telegram_content_posts" USING btree ("chat_id", "media_group_id", "message_thread_id");

CREATE INDEX "ix_telegram_content_posts_media_group_id" ON "public"."telegram_content_posts" USING btree ("media_group_id");

CREATE INDEX "ix_telegram_content_posts_status" ON "public"."telegram_content_posts" USING btree ("status");

